function getHeaders(Key) {

    const { java } = this

    let Header;
    if ( Key == "" ) {
    	    Header = {
    	    	    text: "验证失败，缺少Key"
    	    	}
    	    	java.log("请填入Key");
    	} else {
         let time = Date.now();
         let btime = java.base64Encode(time);
         let sign = Key;

         Header = {
           Key:	 "5pif55ygNTIw",
           Author: "xingmian",
           "X-Source"	: "read.yuedu",
           "Time-Token": String(time),
           "Search-Key-Sign": btime + sign
         }
     }

    return JSON.stringify(Header)

	}

function getContent(result) {

	   const { java } = this

	   let result_url = java.hexDecodeToString(result);

	   return java.ajax(result_url)
